  "topico": "Geometria/Volume",
  "nivel": "Médio",
  "enunciado": "Um reservatório em forma de bloco retangular tem 2 m de comprimento, 3 m de largura e 1 m de altura. Quantos litros de água ele comporta cheio? (1 m³ = 1000 L)",
