  "topico": "Ecologia",
  "nivel": "Médio",
  "enunciado": "A introdução do javali e do mexilhão-dourado no Brasil causou sérios prejuízos ambientais. Espécies exóticas invasoras costumam provocar desequilíbrio porque:",
