  "materia": "matematica",
  "topico": "Equação exponencial",
  "nivel": "Médio",
  "banca": "UNESP",
  "enunciado": "Resolvendo a equação 2ˣ⁺¹ = 32, o valor de x é:",
  "alternativas": [
   "3",
   "4",
   "5",
   "6",
   "2"
  ],
  "correta": 1,
  "explicacao": "32 = 2⁵. Então 2ˣ⁺¹ = 2⁵, logo x + 1 = 5 e x = 4.",
