  "enunciado": "Em uma escola com 700 alunos, 40% foram aprovados sem recuperação. Quanto isso representa?",
  "explicacao": "40% de 700 = 700 × 40/100 = 280.",
  "dica": "X% de V = V × (X ÷ 100). Basta multiplicar.",
