  "explicacao": "Força = peso = m·g = 70 × 10 = 700 N. Área = 25 cm² = 0,0025 m². p = F/A = 700/0,0025 = 280.000 Pa. Quanto menor a área, maior a pressão — por isso o salto fino afunda na grama e a faca afiada corta.",
